for(const lang of LANGS){const t=copy[lang],s=seoHome[lang];t.home.title=s.title;t.home.desc=s.desc;t.home.hero=s.hero;t.home.intro=s.intro;t.home.faqTitle=s.faqTitle}

function homeV2(lang,t){const h=t.home,e=expanded[lang];return `<main><section class="hero"><div class="wrap"><div class="eyebrow">${esc(h.eyebrow)}</div><h1>${h.hero}</h1><p>${esc(h.intro)}</p><div class="buttons">${action(route(lang,'pricing'),h.cta)}${action(route(lang,'reseller'),h.second,true)}</div></div></section><section class="section story"><div class="wrap"><div class="story-heading"><span class="kicker">${esc(h.storyLabel)}</span><h2>${esc(h.storyTitle)}</h2><p>${esc(h.story)}</p></div><div class="grid">${h.storyCards.map(([title,body],i)=>`<article class="card"><span class="step-number">0${i+1}</span><h3>${esc(title)}</h3><p>${esc(body)}</p></article>`).join('')}</div></div></section><section class="section band"><div class="wrap split-band"><div><span class="kicker">ProMax IPTV</span><h2>${esc(e.sectionTitle)}</h2><p>${esc(e.sectionBody)}</p></div>${action(route(lang,'guides'),t.nav[4])}</div></section><section class="section"><div class="wrap"><div class="section-heading"><span class="kicker">ProMax IPTV</span><h2>${esc(t.pricing.hero)}</h2>${action(route(lang,'pricing'),t.misc.allPlans)}</div>${pricingGrid(lang,t,true)}</div></section><section class="section"><div class="wrap"><span class="kicker">${esc(e.sectionTitle)}</span><div class="grid">${e.extras.map(([title,body])=>`<article class="card"><h3>${esc(title)}</h3><p>${esc(body)}</p></article>`).join('')}</div></div></section><section class="section band"><div class="wrap"><h2>${esc(e.howTitle)}</h2><div class="grid">${e.how.map((step,i)=>`<article class="card"><span class="step-number">0${i+1}</span><p>${esc(step)}</p></article>`).join('')}</div></div></section><section class="section faq-section"><div class="wrap"><span class="kicker">FAQ</span><h2>${esc(h.faqTitle)}</h2><div class="faq">${h.faq.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div></div></section></main>`}

function homeV3(lang,t){const s=seoHome[lang];return homeV2(lang,t).replace(`<h2>${esc(t.pricing.hero)}</h2>`,`<h2>${esc(s.subTitle)}</h2>`).replace(/<section class="section faq-section">/,`<section class="section"><div class="wrap split-band"><div><span class="kicker">4K OTT · ProMax IPTV</span><h2>ProMax IPTV — ${esc(t.reseller.hero)}</h2><p>${esc(t.reseller.intro)} ${esc(t.reseller.rule)}</p></div>${action(route(lang,'reseller'),t.nav[2])}</div></section><section class="section band"><div class="wrap split-band"><div><span class="kicker">ProMax IPTV · Free trial</span><h2>${esc(s.trialTitle)}</h2><p>${esc(s.trialBody)}</p></div>${action(orderLink(lang,'a ProMax IPTV free trial'),s.trialButton)}</div></section><section class="section"><div class="wrap split-band"><div><span class="kicker">4K OTT · ProMax IPTV</span><h2>${esc(s.serverTitle)}</h2><p>${esc(s.serverBody)}</p></div>${action(route(lang,'guides'),s.serverButton)}</div></section><section class="section faq-section">`).replace(/<div class="faq">[\s\S]*?<\/div>(?=<\/div><\/section><\/main>$)/,`<div class="faq">${supportFaq[lang].map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div>`)}

function pricingV2(lang,t){const e=expanded[lang];return `<main>${pageHero(lang,t.pricing)}<section class="section"><div class="wrap">${pricingGrid(lang,t)}<p class="reseller-footnote">${esc(t.pricing.foot)}</p></div></section><section class="section band"><div class="wrap"><h2>${esc(e.pricingTitle)}</h2><p class="lead">${esc(e.pricingBody)}</p></div></section><section class="section"><div class="wrap"><div class="faq">${e.pricingFaq.map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}</div></div></section></main>`}

function resellerV2(lang,t){const base=reseller(lang,t);const e=expanded[lang];const extra=`<section class="section band"><div class="wrap"><h2>${esc(e.resellerTitle)}</h2><p class="lead">${esc(e.resellerBody)}</p><div class="grid">${e.resellerSteps.map(([title,body],i)=>`<article class="card"><span class="step-number">0${i+1}</span><h3>${esc(title)}</h3><p>${esc(body)}</p></article>`).join('')}</div></div></section><section class="section"><div class="wrap split-band"><div><h2>${esc(t.reseller.hero)}</h2><p class="lead">${esc(t.reseller.rule)}</p></div>${action(orderLink(lang,'ProMax IPTV reseller credits'),t.reseller.button)}</div></section>`;return base.replace('</main>',`${extra}</main>`)}

function blogV2(lang,t){const e=expanded[lang];return `<main>${pageHero(lang,t.blog)}<section class="section"><div class="wrap article-list">${e.articleTitles.map((title,i)=>`<article class="article-card"><div class="article-meta"><span>${esc(t.blog.hero)}</span><span>${esc(e.authors[i])} · Editorial pen name</span></div><h2>${esc(title)}</h2>${e.articleBodies[i].map(paragraph=>`<p>${esc(paragraph)}</p>`).join('')}<div class="article-links">${action(route(lang,i===1?'apps':i===2?'reseller':'pricing'),t.misc.learn)}</div></article>`).join('')}</div></section></main>`}

function render(lang,page){const t=copy[lang],data=t[page];const body=({home:homeV3,pricing:pricingV2,reseller:resellerV2,apps,guides,blog:blogV2,contact}[page]||info)(lang,t,page).replace('ProMax IPTV · 4K OTT · Cobra OTT','ProMax IPTV · 4K OTT');return `<!doctype html><html lang="${t.locale}">${head(lang,page,data)}<body><noscript><iframe src="https://www.googletagmanager.com/ns.html?id=GTM-5KDCZQT8" height="0" width="0" style="display:none;visibility:hidden" title="Google Tag Manager"></iframe></noscript>${header(lang,page,t)}${body}${footerV2(lang,t)}</body></html>`}

for(const lang of LANGS){for(const page of PAGES){const folder=path.join(OUT,lang,page==='home'?'':page);fs.mkdirSync(folder,{recursive:true});fs.writeFileSync(path.join(folder,'index.html'),render(lang,page),'utf8')}}
const rootRedirect='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="google-site-verification" content="PJAxWnHKxy949O0rwdvPcPaPz1Ixv0Nd-QAezi1DN34"><meta http-equiv="refresh" content="0;url=/en/"><link rel="canonical" href="https://4k-ott.tv/en/"><title>ProMax IPTV — 4K OTT</title></head><body><a href="/en/">Continue to English</a></body></html>';
fs.writeFileSync(path.join(OUT,'index.html'),render('en','home'),'utf8');
for(const page of PAGES.filter(p=>p!=='home')){const folder=path.join(OUT,page);fs.mkdirSync(folder,{recursive:true});fs.writeFileSync(path.join(folder,'index.html'),rootRedirect.replaceAll('/en/','/en/'+page+'/'))}
const urls=LANGS.flatMap(lang=>PAGES.map(page=>`<url><loc>${BASE}${route(lang,page)}</loc>${LANGS.map(code=>`<xhtml:link rel="alternate" hreflang="${copy[code].locale}" href="${BASE}${route(code,page)}"/>`).join('')}</url>`));
fs.writeFileSync(path.join(OUT,'sitemap.xml'),`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9" xmlns:xhtml="http://www.w3.org/1999/xhtml">${urls.join('')}</urlset>`);
fs.writeFileSync(path.join(OUT,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${BASE}/sitemap.xml\n`);
console.log(`Generated ${LANGS.length*PAGES.length} localized pages.`);
